    ('7279cb69-c5d2-4b9b-b307-96ef43164e7f'::uuid, 'period_name', '3000 - 1500 BC', NULL, 'fields-wd3-2026-10-02b-s005-rollback:7279cb69-c5d2-4b9b-b307-96ef43164e7f:period_name', 'rollback of fields-wd3-2026-10-02b-s005: period_name None restored on Crantit Chambered Cairn', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0271)", "decision": "replace", "status": "MISSING", "reasoning": "The Ness of Brodgar Project - the team that excavated this chamber in 1998 - reports that the excavators dated the Crantit chamber itself to the late Neolithic, c3000-2500BC; the bones could not be radiocarbon dated, but this is a date for this tomb and not a range for a class of monuments, so the start is 3000 BC (-3000).", "value_page": null, "model": "minimax/MiniMax-M3.1-Flash-Preview (MiniMax Code agent)"}]'::jsonb),
